#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    if (cin >> n) {
        vector<vector<int>> a(n, vector<int>(n, 0));
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j <= i; ++j) {
                cin >> a[i][j];
            }
        }
        // 从倒数第二层开始向上推导
        for(int i = n - 2; i >= 0; --i) {
            for(int j = 0; j <= i; ++j) {
                a[i][j] += max(a[i+1][j], a[i+1][j+1]);
            }
        }
        cout << a[0][0] << "\n";
    }
    return 0;
}
